n=22
grid=[[0]*n for _ in range(n)]
objs=[(1,0,8,1),(2,17,2,7),(3,5,8,5),(7,12,2,5),(9,17,2,9),(13,12,2,3),(16,17,2,6),(15,0,8,6)]
for r,c,border,center in objs:
    for dr in range(5):
        for dc in range(5):
            grid[r+dr][c+dc] = center if 1<=dr<=3 and 1<=dc<=3 else border
print('\n'.join(' '.join(map(str,row)) for row in grid))
print([len(row) for row in grid])
